<?php
declare(strict_types=1);
require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../config/db.php';
require_once __DIR__.'/../../config/mpesa.php';require_once __DIR__.'/../../includes/audit.php';
if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: index.php');exit;}verify_csrf();
requireModulePermission('customer_payments','create');
try{$cid=(int)($_POST['customer_id']??0);$amount=(float)($_POST['amount']??0);$method=(string)($_POST['payment_method']??'Cash');$ref=trim((string)($_POST['transaction_reference']??''));$phone=trim((string)($_POST['mpesa_phone']??''));$notes=trim((string)($_POST['notes']??''));if($cid<=0||$amount<=0)throw new RuntimeException('Select a customer and enter a valid amount.');if(!in_array($method,['Cash','M-Pesa','Bank','Cheque','Other'],true))throw new RuntimeException('Invalid payment method.');if($method==='M-Pesa'&&$phone==='')throw new RuntimeException('Enter the customer M-PESA phone number.');if($method==='Cash'&&hasModulePermission('cash_management','create')&&(bool)$conn->query("SHOW TABLES LIKE 'cash_shift_guard'")->fetchColumn()){$shiftQ=$conn->prepare("SELECT id FROM cash_shifts WHERE user_id=? AND status='Open' LIMIT 1");$shiftQ->execute([(int)$_SESSION['user_id']]);if(!$shiftQ->fetchColumn())throw new RuntimeException('Open your cashier shift before receiving a cash customer payment.');}
$conn->beginTransaction();$s=$conn->prepare("SELECT * FROM customers WHERE id=? AND status='Active' FOR UPDATE");$s->execute([$cid]);$c=$s->fetch();if(!$c)throw new RuntimeException('Customer not found.');$balance=(float)$c['balance'];if($balance<=0)throw new RuntimeException('This customer has no outstanding balance.');if($amount>$balance+.001)throw new RuntimeException('Payment cannot exceed outstanding balance of KES '.number_format($balance,2));
$receipt='MP-'.date('ymd').'-'.str_pad((string)random_int(1,99999),5,'0',STR_PAD_LEFT);$uid=(int)$_SESSION['user_id'];
if($method==='M-Pesa'){
 $conn->commit();
 try{$resp=mpesaStkPush($amount,$phone,$receipt,'Credit payment '.$receipt);
   $tx=$conn->prepare("INSERT INTO mpesa_transactions(transaction_type,direction,phone_number,amount,account_reference,merchant_request_id,checkout_request_id,result_code,result_description,result_status,reference_type,reference_id,raw_response) VALUES('STK Push','Incoming',?,?,?,?,?,?,?,?,?,?,?)");
   $tx->execute([$phone,$amount,$receipt,$resp['MerchantRequestID']??null,$resp['CheckoutRequestID']??null,(string)($resp['ResponseCode']??''),(string)($resp['ResponseDescription']??''),!empty($resp['CheckoutRequestID'])?'Pending':'Failed','customer_payment',$cid,json_encode($resp)]);
   $_SESSION['payment_flash']='M-PESA STK Push sent to '.$phone.'. The customer payment will be posted after confirmation.';
 }catch(Throwable $mp){$_SESSION['payment_flash']='M-PESA request failed: '.$mp->getMessage();}
 header('Location: index.php');exit;
}
$s=$conn->prepare("INSERT INTO customer_payments (receipt_number,customer_id,sale_id,user_id,amount,payment_method,transaction_reference,payment_date,notes) VALUES (?,?,?,?,?,?,?,?,?)");$s->execute([$receipt,$cid,null,$uid,$amount,$method,$ref?:null,date('Y-m-d H:i:s'),$notes?:null]);$paymentId=(int)$conn->lastInsertId();$receipt='CR-'.date('ymd').'-'.str_pad((string)$paymentId,5,'0',STR_PAD_LEFT);$conn->prepare("UPDATE customer_payments SET receipt_number=? WHERE id=?")->execute([$receipt,$paymentId]);$s=$conn->prepare("UPDATE customers SET balance=balance-? WHERE id=?");$s->execute([$amount,$cid]);$s=$conn->prepare("INSERT INTO activity_logs (user_id,action,module,description,ip_address) VALUES (?,?,?,?,?)");$s->execute([$uid,'Receive','Customer Payments','Received '.$receipt.' of KES '.number_format($amount,2),$_SERVER['REMOTE_ADDR']??null]);recordAuditEvent($conn,'Receive','customer_payments','Received customer payment '.$receipt.' of KES '.number_format($amount,2),'customer_payment',$paymentId,null,['customer_id'=>$cid,'amount'=>$amount,'payment_method'=>$method,'reference'=>$ref?:null]);$conn->commit();$_SESSION['payment_flash']='Payment '.$receipt.' recorded successfully.';}catch(Throwable $e){if($conn->inTransaction())$conn->rollBack();$_SESSION['payment_flash']='Payment failed: '.$e->getMessage();}header('Location: index.php');exit;